 Map<String,Object> request(Map<String,?> fields){var r=new LinkedHashMap<String,Object>();r.put("expectedRevisionToken",Long.toString(revision()));r.putAll(fields);return r;}
 com.fasterxml.jackson.databind.JsonNode write(String method,String path,Map<String,Object> request,String key,List<Map<String,Object>> steps)throws Exception{long before=revision();var response=call(method,"/meetings/"+meeting+"/minutes"+path,json.writeValueAsString(request),key);Files.writeString(receipt.resolve(key+"-response.json"),json.writeValueAsString(Map.of("status",response.statusCode(),"body",response.body())),StandardOpenOption.CREATE_NEW);assertEquals(200,response.statusCode(),path+" "+response.body());assertEquals(before+1,revision());steps.add(Map.of("operation",key,"status",200,"before",before,"after",revision()));return body(response);}
 void writeReplay(String method,String path,Map<String,Object> request,String key)throws Exception{var response=call(method,"/meetings/"+meeting+"/minutes"+path,json.writeValueAsString(request),key);assertEquals(200,response.statusCode());assertTrue(body(response).path("replayed").asBoolean());}
 String current(String column){assertTrue(Set.of("minutes_revision_id","element_set_id","exclusion_revision_id").contains(column));return j.queryForObject("SELECT "+column+" FROM meeting WHERE id=?",String.class,meeting);}
 String action(String set){return j.queryForObject("SELECT id FROM minutes_element WHERE set_id=? AND category='ACTION' ORDER BY ordinal LIMIT 1",String.class,set);}
 List<Map<String,Object>> anchors(String column,String id){assertTrue(Set.of("minutes_revision_id","element_id").contains(column));return j.queryForList("SELECT id FROM evidence_link WHERE "+column+"=? ORDER BY id",String.class,id).stream().map(e->Map.<String,Object>of("evidenceId",e,"startToken","0","endToken","7")).toList();}
 Map<String,List<Map<String,Object>>> originalFacts(){var r=new TreeMap<String,List<Map<String,Object>>>();r.put("final_confirmation",j.queryForList("SELECT * FROM final_confirmation WHERE id=?",confirmationId));r.put("final_result_review",j.queryForList("SELECT * FROM final_result_review WHERE confirmation_id=? ORDER BY review_id",confirmationId));r.put("publication_submission",j.queryForList("SELECT * FROM publication_submission WHERE task_id=?",publicationTask));r.put("publication_attempt",j.queryForList("SELECT * FROM publication_attempt WHERE publication_id=? ORDER BY id",publicationId));for(String table:List.of("durable_task","task_attempt","external_execution"))r.put(table,j.queryForList("SELECT * FROM "+table+" WHERE "+(table.equals("durable_task")?"id":"task_id")+"=? ORDER BY "+(table.equals("task_attempt")?"attempt":"id"),publicationTask));r.put("external_operation",j.queryForList("SELECT * FROM external_operation WHERE id IN(SELECT operation_id FROM external_execution WHERE task_id=?) ORDER BY id",publicationTask));return r;}
 Map<String,List<Map<String,Object>>> business(){var r=new TreeMap<String,List<Map<String,Object>>>();for(String table:List.of("meeting","minutes_revision","element_set","minutes_element","action_item","action_suggestion","evidence_link","result_review","result_review_evidence","generation_candidate","meeting_minutes_editor_guard","final_confirmation","final_result_review","publication","publication_submission","publication_attempt","external_document_mapping","durable_task","task_attempt","external_operation","external_execution","idempotency_record","task_outbox","task_outbox_sequence","task_subject","meeting_search_projection","audit_event")){var rows=j.queryForList("SELECT * FROM "+table);assertTrue(rows.size()<=2048);rows.sort(Comparator.comparing(Object::toString));r.put(table,rows);}return r;}
